(@phb_source_id, 'aggressore-selvaggio', 'Aggressore selvaggio', 'origin', 0, '[]', 'Migliora una volta per turno l''affidabilita dei danni con arma.', '{"tags":["armi","danni"],"choices":[],"effects":[],"source":{"manual":"Manuale del Giocatore","edition":"2024","language":"it","pages_pdf":[203]},"category_label":"Origini"}'),
(@phb_source_id, 'allerta', 'Allerta', 'origin', 0, '[]', 'Migliora iniziativa e scambio tattico con un alleato.', '{"tags":["iniziativa"],"choices":[],"effects":[],"source":{"manual":"Manuale del Giocatore","edition":"2024","language":"it","pages_pdf":[203]},"category_label":"Origini"}'),
(@phb_source_id, 'fortunato', 'Fortunato', 'origin', 0, '[]', 'Aggiunge punti fortuna spendibili su prove con d20 e attacchi contro il personaggio.', '{"tags":["risorsa","d20"],"choices":[],"effects":[{"type":"resource","id":"luck_points","scales_with":"proficiency_bonus","resetOn":"long_rest"}],"source":{"manual":"Manuale del Giocatore","edition":"2024","language":"it","pages_pdf":[204]},"category_label":"Origini"}'),
